styles.css:
.wp-travel-book ,
.wp-element-button,
.wpcf7-submit,
.wp-block-button__link {
    background: #595F39;
    color: #fff;
    font-size: 14px;
    padding: 12px 24px !important;
border-radius: 10px!important;
}

.wp-travel-book:hover ,
input.wp-element-button:hover,
.wpcf7-submit:hover,
.wp-block-button__link:hover,
input.wp-element-button:focus,
.wpcf7-submit:focus,
.wp-block-button__link:focus, .wp-element-button:hover {
    background-color: #1B1B1B !important;
    color: #fff !important; 
}
input#wp-travel-enquiry-submit {
     background: #65ABEA;
    color:#fff;
    border-radius: 10px !important;
}
input#wp-travel-book-now {
    background: #65ABEA;
    color:#fff;
    font-size: 15px;
    padding: 15px 30px !important;
    border-radius: 10px !important;
}

.page-numbers.current,
a:focus,
a:hover{
color: var(--wp--preset--color--secondary);
}

.wp-block-query-pagination a,
.wp-block-comment-date a,
.wp-block-comment-author-name a,
.wp-block-navigation-submenu a,
.wp-block-navigation-link a,
.wp-block-categories a,
.wp-block-post-title a,
.wp-block-site-title a{
   text-decoration: none !important;
}

.about-section-image-relative{
    z-index: 2;
    position: relative !important;
}


.testimonial-relative-post-content,
.about-relative-post-content{
z-index: 2;
    position: relative !important;
}

.wpcf7-text{
width: 100%;
height: 30px;
}

.wpcf7-textarea{
width: 100%;
}

.single .wp-block-post-terms a {
    border-radius: 2px;
    padding: 5px;
    margin: 5px;
    text-decoration: none;
}

@media only screen and (max-width: 1000px) {
  .mobile-disable{
      display:none !important;
  }
}

:root :where(.wp-element-button, .wp-block-button__link) {
   border-width: 0px;
}
.ac .ac-trigger {
    padding: 16px 32px 16px 16px!important;

}
.ac-header, .ac-panel {
     border-radius: 10px!important;
}
.ac {
    border-radius: 10px!important;
}


input.wpcf7-form-control.wpcf7-text.wpcf7-validates-as-required, input.wpcf7-form-control.wpcf7-tel.wpcf7-text.wpcf7-validates-as-tel {
    border: solid 1px #eee;
    height: 40px;
    border-radius: 10px;
padding-left: 10px;
}
.wpcf7-textarea{
   border: solid 1px #eee;
    border-radius: 10px;
}
#wp-travel-tab-content-address select {
    height: 48px!important;
}
.wptravel-block-trip-filters .wp-travel-itinerary-items .wp-travel-form-field select, .wptravel-block-trip-filters .wp-travel-itinerary-items .wp-travel-form-field input
 {
    padding: 10px!important;
    border: 1px solid #ccc!important;
    outline: 0;
    background: #fff!important;
    border-radius: 8px!important;
}
.wptravel-block-trip-filters .wp-travel-itinerary-items .wp-travel-form-field {
    margin-bottom: 20px!important;
}
.wp-trave-price-range .ui-widget.ui-widget-content {
    top: 12px;
}
.tour-info .tour-info-box {
    border-radius: 8px!important;
}
.wptravel-block-trip-filters .wp-travel-itinerary-items .wp-travel-form-field label
 {
color:#fff!important;
}
.wptravel-block-trip-filters .wp-trave-price-range .ui-slider-horizontal .ui-slider-range {
    top: 0;
    height: 100%;
    background: #ccc;
}
.wp-trave-price-range .ui-state-default, .wp-trave-price-range .ui-widget-content .ui-state-default{
background: #E4E4DE!important;
}
#wptravel-scroll-to-top {
    display: none!important;
}
.wptravel-guide-image-block {
    height: auto!important;
    width: 100%!important;
    border-radius: 10px;
}
.wp-travel-book, .wp-element-button, .wpcf7-submit, .wp-block-button__link {
   background: #595F39!important;
    color: #fff!important;
    font-size: 14px;
    padding: 12px 24px !important;
border-radius: 10px!important;
}
.wptravel-travel-guide-Review {
    position: relative;
    margin-bottom: 30px;
    border: solid 1px #ccc;
    padding: 20px;
    z-index: 0;
}
.wptravel-guide-review-form-block .section-title,.wptravel-guide-review-form-block #reply-title{
font-size: 24px;
}
.wptravel-travel-guide-Review {
    border: solid 2px #c4c5ba!important;
    border-radius: 10px!important;
}

