.comment-reply-title{
font-size:24px!important;
}
.wp-travel-booking__panel-bottom {
    z-index: 9999!important;
}
input#wp-travel-book-now {
    background: #595F39!important;
    color: #fff;
border: none;
}
#wp-travel-tab-content-bookings .my-order table.order-list-table td .contact-title a{
  background: #595F39!important;
    color: #fff;
    padding: 8px 24px!important;
border-radius: 10px!important;
}
#wp-travel-tab-content-bookings .my-order .book-more a{
    background-color: #31708f;
   background: #595F39!important;
    font-size: 14px;
    padding: 12px 24px !important;
border-radius: 10px!important;

}
#wp-travel-tab-content-account .button, #wp-travel-tab-content-address .button {
   background: #595F39!important;
    font-size: 14px;
    padding: 12px 24px !important;
border-radius: 10px!important;
border: none!important;
}
#wp-travel-tab-content-address select , .dashboard-tab input.form-control{
    padding: 14px!important;
border-radius: 10px!important;
}
.dashboard-tab ul.resp-tabs-list {
     background: #595F39!important;
}
.dashboard-tab ul.resp-tabs-list li {
    color: #ffffff!important;
}
.dashboard-tab ul.resp-tabs-list li.resp-tab-active {
    color: #29324e!important;
}
#wptravel-block-trip-categories{
color: #fff!important;
}
.wp-travel-average-review span::before {
    font-family: "wt-icon-solid";
}

.search-box {
    max-width: 1320px;
    margin: auto;
    background: #ddd8cf;
    border-radius: 18px;
    padding: 5px 30px 30px;
}

.search-text {
    width: 91% !important;
}

.search-box h2 {
    font-size: 20px;
    font-weight: 700;
    color: #111;
    margin-bottom: 0px;
}

.trip-form{
    display:grid;
    grid-template-columns:1.2fr 1fr 1fr 1.2fr;
    gap:15px;
    align-items:end;
}

.form-group{
    width:100%;
}

.form-group label{
    display:block;
    font-size:16px;
    font-weight:500;
    color:#222;
    margin-bottom:8px;
}

.form-group input,
.form-group select{
    width:100%;
    height:46px;
    border:none;
    border-radius:10px;
    background:#fff;
    padding:0 15px;
    font-size:15px;
    outline:none;
}

.form-group input::placeholder{
    color:#999;
}

.form-btn{
    width:100%;
}

.form-btn button{
    width:100%;
    height:46px;
    border:none;
    border-radius:10px;
    background:#6a6b3d;
    color:#fff;
    font-size:16px;
    font-weight:600;
    cursor:pointer;
    transition:.3s;
}

.form-btn button:hover{
    background:#5c5d35;
}

@media(max-width:992px){

    .search-box{
        padding:20px;
    }

    .trip-form{
        grid-template-columns:1fr;
    }

    .search-box h2{
        font-size:28px;
        margin-bottom:15px;
    }

    .form-btn button{
        width:100%;
    }
}
